To create a Chrome extension that takes screenshots of all tabs in a window and saves them in a folder, follow these steps:

1. Create a new folder for your extension and create the following files inside it:
   - `manifest.json`
   - `background.js`
   - `content_script.js`
   - `screenshot.html`

2. Open `manifest.json` and add the following content:

```json
{
  "manifest_version": 3,
  "name": "Tab Screenshot",
  "version": "1.0",
  "action": {
    "default_popup": "screenshot.html"
  },
  "permissions": [
    "activeTab",
    "tabs",
    "storage",
    "downloads",
    "fileSystem"
  ],
  "background": {
    "service_worker": "background.js"
  },
  "content_scripts": [
    {
      "matches": ["*://*/*"],
      "js": ["content_script.js"]
    }
  ],
  "icons": {
    "16": "icon16.png",
    "48": "icon48.png",
    "128": "icon128.png"
  }
}
```

Replace the `icons` section with your own icons if needed.

3. Open `background.js` and add the following content:

```javascript
chrome.runtime.onInstalled.addListener(function() {
  if (chrome.runtime.lastError) {
    console.log(chrome.runtime.lastError.message);
    return;
  }

  // Create a folder to save screenshots
  chrome.fileSystem.createDirectory({
    path: "Screenshots",
    createInside: true,
    success: function(directoryEntry) {
      console.log("Directory created:", directoryEntry.fullPath);
    },
    error: function(error) {
      console.log("Error creating directory:", error.code);
    }
  });
});

chrome.tabs.onUpdated.addListener(function(tabId, changeInfo, tab) {
  if (changeInfo.status === "complete" && tab.active) {
    chrome.tabs.captureVisibleTab(tabId, function(screenshot) {
      chrome.fileSystem.writeFile(
        {
          path: "Screenshots/tab" + tab.id + ".png",
          data: screenshot,
          encoding: "base64",
          mimeType: "image/png"
        },
        function(writeEntry) {
          console.log("Screenshot saved:", writeEntry.fullPath);
        },
        function(error) {
          console.log("Error saving screenshot:", error.code);
        }
      );
    });
  }
});
```

