  const portfolioCurrentRef = useRef(null);
  const portfolioNextRef = useRef(null);
  const cursorRef = useRef({ cursorImage: '' });
  const debounceRef = useRef(null);

  useEffect(() => {
    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }
    debounceRef.current = setTimeout(() => {
      // Your code here
