First, install the necessary libraries:

```bash
npm install xlsx lodash
```

Then, create a script to compare the files:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareExcelFiles(file1, file2, callback) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet_name_list1 = workbook1.SheetNames;
  const sheet_name_list2 = workbook2.SheetNames;

  let differences = [];

  // Compare each sheet name by name
  const commonSheets = _.intersection(sheet_name_list1, sheet_name_list2);
  commonSheets.forEach(sheetName => {
    const worksheet1 = workbook1.Sheets[sheetName];
    const worksheet2 = workbook2.Sheets[sheetName];

    const data1 = _.map(XLSX.utils.sheet_to_json(worksheet1), row => row.A);
    const data2 = _.map(XLSX.utils.sheet_to_json(worksheet2), row => row.A);

    const differencesInThisSheet = _.differenceWith(data1, data2, _.isEqual);
    differences = differences.concat(differencesInThisSheet);
  });

  // Compare sheets that only exist in one of the files
  const uniqueSheets1 = _.difference(sheet_name_list1, sheet_name_list2);
  uniqueSheets1.forEach(sheetName => {
    const worksheet1 = workbook1.Sheets[sheetName];
    const data1 = _.map(XLSX.utils.sheet_to_json(worksheet1), row => row.A);
    differences = differences.concat(data1);
  });

  const uniqueSheets2 = _.difference(sheet_name_list2, sheet_name_list1);
  uniqueSheets2.forEach(sheetName => {
    const worksheet2 = workbook2.Sheets[sheetName];
    const data2 = _.map(XLSX.utils.sheet_to_json(worksheet2), row => row.A);
    differences = differences.concat(data2);
  });

  callback(differences);
}

